// MARK: - Type

/// Text sizes, each with its line height (a multiple of the size) and the Apple text style it scales
/// with under Dynamic Type. Use with `.labbText(_:)`.
public enum LabbTextStyle: String, CaseIterable, Sendable {
    /// Mono labels, table heads, counts
    case xxs
    /// Hints, small print, badges
    case xs
    /// Controls, sidebar, tables
    case sm
    /// Secondary body, toasts
    case md
    /// Body text
    case base
    /// Small headings
    case lg
    /// Page titles
    case xl
    /// Section headings
    case xxl
    /// The empty chat's greeting
    case xxxl

    /// The size in points, before Dynamic Type
    public var size: CGFloat {
        switch self {
        case .xxs: 11
        case .xs: 12
        case .sm: 13
        case .md: 14
        case .base: 15
        case .lg: 17
        case .xl: 20
        case .xxl: 24
        case .xxxl: 32
        }
    }

    /// The line height, as a multiple of the size
    public var lineHeight: CGFloat {
        switch self {
        case .xxs: 1.4
        case .xs: 1.45
        case .sm: 1.5
        case .md: 1.55
        case .base: 1.55
        case .lg: 1.4
        case .xl: 1.3
        case .xxl: 1.2
        case .xxxl: 1.1
        }
    }

    /// The text style it scales with
    public var relativeTo: Font.TextStyle {
        switch self {
        case .xxs: .caption2
        case .xs: .caption
        case .sm: .footnote
        case .md: .subheadline
        case .base: .subheadline
        case .lg: .body
        case .xl: .title3
        case .xxl: .title2
        case .xxxl: .largeTitle
        }
    }
}

