/// A shadow: solid and offset, never blurred (except the soft ones). `.labbShadow(_:)` draws it.
public struct LabbShadow: Sendable {
    public let x: CGFloat
    public let y: CGFloat
    public let blur: CGFloat
    public let spread: CGFloat
    public let color: Color
    /// Drawn inside the shape's leading edge, like the yellow bar on what's open
    public let inset: Bool

    /// Under yellow buttons at rest
    public static var press: LabbShadow { LabbShadow(x: 2, y: 2, blur: 0, spread: 0, color: Color.labb.press, inset: false) }
    /// Under yellow buttons on hover
    public static var pressHover: LabbShadow { LabbShadow(x: 3, y: 3, blur: 0, spread: 0, color: Color.labb.press, inset: false) }
    /// Toasts
    public static var toast: LabbShadow { LabbShadow(x: 4, y: 4, blur: 0, spread: 0, color: Color.labb.hard, inset: false) }
    /// Menus, popovers, dialogs, tooltips
    public static var popover: LabbShadow { LabbShadow(x: 5, y: 5, blur: 0, spread: 0, color: Color.labb.hard, inset: false) }
    /// Cards on hover, the focused message box
    public static var lift: LabbShadow { LabbShadow(x: 4, y: 4, blur: 0, spread: 0, color: Color.labb.accentFill, inset: false) }
    /// The yellow bar on what's open
    public static var bar: LabbShadow { LabbShadow(x: 3, y: 0, blur: 0, spread: 0, color: Color.labb.accentFill, inset: true) }
    /// A picked segment
    public static var soft: LabbShadow { LabbShadow(x: 0, y: 1, blur: 2, spread: 0, color: Color(.sRGB, red: 0, green: 0, blue: 0, opacity: 0.1), inset: false) }
    /// Under a switch's knob
    public static var knob: LabbShadow { LabbShadow(x: 0, y: 1, blur: 2, spread: 0, color: Color(.sRGB, red: 0, green: 0, blue: 0, opacity: 0.25), inset: false) }
}

